/* Missing-screen pass: local interaction specimens, never backend execution. */
(() => {
 const U=window.NestUI,e=v=>U.escape(v),b=(v,t)=>U.badge(v,t),l=(id,label,primary=false)=>`<a class="btn ${primary?'btn-primary':''}" href="#${id}">${label}</a>`,logo=(n)=>U.logo?.(n)||'', money=n=>n==null?'Unavailable':'$'+Number(n).toLocaleString('en-US',{maximumFractionDigits:2}),p=()=>new URLSearchParams(location.hash.split('?')[1]||'');
 const top=(scope,title,sub,actions='')=>`<div class="page-head"><div><span class="eyebrow">${scope}</span><h1>${title}</h1><p>${sub}</p></div><div class="page-head-actions">${actions}</div></div>`;
 const panel=(title,body,aside='')=>`<section class="panel"><div class="panel-head"><h2>${title}</h2>${aside}</div><div class="panel-body">${body}</div></section>`;
 const facts=rows=>`<dl class="details-list">${rows.map(([k,v])=>`<div><dt>${k}</dt><dd>${v}</dd></div>`).join('')}</dl>`;
 const table=(heads,rows)=>`<div class="table-wrap"><table class="data-table"><thead><tr>${heads.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
 const field=(label,input,help='')=>`<label class="field"><span class="field-label">${label}</span>${input}${help?`<small>${help}</small>`:''}</label>`;
 const inp=(name,value,extra='')=>`<input class="input" name="${name}" value="${e(value)}" ${extra}>`;
 const tabs=(active,items)=>`<nav class="tabs" aria-label="${active} navigation">${items.map(([id,label])=>`<a class="tab ${active===id?'active':''}" href="#${id}">${label}</a>`).join('')}</nav>`;
 const foot='<p class="data-note mt-24">Illustrative account and action values · no wallet, live quote, submission or persistent account changes.</p>';
 const timing='<div class="disclosure"><b>When can I withdraw?</b><br>Available pool liquidity and any collateral obligation govern the exit. Templar may require a queue and external settlement. Exact timing is refreshed before review; unknown timing remains explicit.</div>';
 const ident=(name,detail='')=>`<div class="c-identity">${logo(name)}<div><b>${e(name)}</b>${detail?`<small>${e(detail)}</small>`:''}</div></div>`;
 const S=window.NestScreens,B=window.NestBinders;
 const creditTabs=[['borrow','Borrow'],['supply','Supply'],['positions','My positions']];
 const portfolioTabs=[['portfolio','Overview'],['activity','Activity'],['fund','Receive'],['transfer','Send'],['vault-management','Redemptions']];
 S['protocol-detail']=()=>{
 const data=window.NestResearchSnapshot,slug=p().get('slug')||'blend-pools-v2',d=data.protocols.find(x=>x.slug===slug)||data.protocols.find(x=>x.name==='Blend Pools V2');
 const eligible=/blend|templar|xoxno|soroswap/i.test(d.name),url=d.url?.startsWith('https://')?d.url:'https://defillama.com/chain/stellar';
 return top('Research / Protocol',`${logo(d.name)} ${e(d.name)}`,e(d.description||'Protocol description unavailable in the captured source.'),l('research-defi','← All protocols')+`<button class="btn" data-bookmark="${e(d.name)}">Save protocol</button>`)+`<div class="c-detail-grid"><div class="stack"><div class="panel metric-grid">${U.stat('Stellar TVL',money(d.stellar_tvl_usd),'Provider snapshot · 25 Oct 2026')}${U.stat('Protocol-wide TVL',money(d.protocol_tvl_all_chains_usd),`${d.protocol_chains.length} chains · distinct scope`)}${U.stat('Category',e(d.category),'Source classification')}</div>`+panel('Market access',table(['Market','Mode','Availability','Action'],[['USDC','Supply',eligible?'Adapter verification required':'Unsupported integration',eligible?l('supply','Compare supply'):b('Research only')],['XLM / USDC','Borrow',eligible?'Capacity and native risk checked at quote time':'No registered executable market',eligible?l('borrow','Compare borrowing'):b('Unavailable')]]))+panel('History & coverage','<div class="c-coverage"><span class="eyebrow">Protocol history</span><h3>Historical series not captured</h3><p>Chain history is available in the DeFi overview. It does not represent this protocol’s history.</p></div>')+panel('Dependencies & controls',facts([['Network','Stellar · issuer and contract resolution required'],['Audit evidence',d.audit_links?.length?d.audit_links.map(a=>`<a href="${e(a)}" target="_blank" rel="noopener">Source audit ↗</a>`).join(' · '):'No audit report verified in this snapshot'],['Admin / upgrade controls','Not captured · inspect verified documentation before action'],['Oracle / liquidation source','Adapter-specific facts required'],['Source timestamp',e(d.observed_at)]]))+`</div><aside class="stack">`+panel('Explore this protocol',`${ident(d.name,d.category)}<p class="muted mt-24">Discovery metrics do not establish executable capacity or eligibility.</p>${l('vaults','View opportunities',true)}<a class="btn full-width mt-24" href="${e(url)}" target="_blank" rel="noopener">Protocol website ↗</a>`)+panel('Source boundaries','<p class="muted">TVL is a source-defined metric. All-chain changes, chain-specific value and execution quotes retain their own definitions.</p><a href="https://defillama.com/chain/stellar" target="_blank" rel="noopener">DefiLlama source ↗</a>')+'</aside></div>';
 };
 S['asset-detail']=()=>{const ds=window.NestResearchSnapshot.rwa.assets;const a=ds.find(a=>a.identity===p().get('id'))||ds.find(a=>a.ticker==='BENJI');return top('Research / RWA asset',`${logo(a.name)} ${e(a.name)}`,'Source-reported identity, issuance facts, and access conditions.',l('research-rwa','← RWAs')+`<button class="btn" data-bookmark="${e(a.name)}">Save asset</button>`)+`<div class="c-detail-grid"><div class="stack"><div class="panel metric-grid">${U.stat('Source total value',e(a.totalValueDisplay.replace(/\s+/g,' ')),'RWA.xyz · source-defined value')}${U.stat('Holders',e(a.holdersDisplay.replace(/\s+/g,' ')),'Not a liquidity measure')}${U.stat('Tokenization',e(a.tokenizationType),'Never add to DeFi TVL')}</div>`+panel('Asset identity',facts([['Ticker / network',e(a.ticker)+' · Stellar'],['Canonical identity',`<a class="c-wrap mono" href="${e(a.contractExplorerUrl)}" target="_blank" rel="noopener">${e(a.contractExplorerUrl.split('/').pop())} ↗</a>`],['Identity verification',b('Source reported · execution unverified','warning')],['Platform',ident(a.platform)],['Manager',e(a.manager||'Not supplied')],['Class / domicile',e(a.assetClass)+' · '+e(a.domicile)],['Regulatory framework',e(a.regulatoryFramework)]]))+panel('Value and trading coverage','<div class="c-coverage"><h3>No price or liquidity series captured</h3><p>Issuance value does not establish a swap quote. No fabricated chart is shown.</p></div>')+`</div><aside class="stack">`+panel('Access & redemption',facts([['Investor eligibility','Unknown · issuer review required'],['Subscriptions','Issuer terms required'],['Redemption window','Unknown · verify directly'],['Secondary liquidity','No executable route verified']])+`<a class="btn full-width mt-24" href="${e(a.assetUrl)}" target="_blank" rel="noopener">RWA.xyz asset record ↗</a>`)+panel('Execution unavailable','<p class="muted">This asset remains research-only until identity, eligibility and a registered adapter are verified.</p>'+b('Research only','warning'))+'</aside></div>';};
 const saved=[['Blend Pools V2','Protocol','USDC lending, Stellar','protocol-detail'],['BENJI','RWA asset','Treasury funds, source identity','asset-detail'],['Stellar lending','Saved filter','USDC · supply · liquidity-aware','supply']];let removed=new Set();
 S.saved=()=>top('Research / Library','Saved research','Keep protocols, assets and reusable public filters together.',l('research-defi','Explore research'))+`<div class="alert alert-info mb-24">Guest library specimen · connect and verify ownership to persist bookmarks.</div><div class="toolbar"><input class="input" id="c-saved-search" aria-label="Search saved items" placeholder="Search saved research…"><button class="btn" data-export-saved>Export library</button></div><div id="c-saved-items" class="stack mt-24"></div>`;
 B.saved=root=>{const render=()=>{const q=root.querySelector('input').value.toLowerCase();root.querySelector('#c-saved-items').innerHTML=saved.filter(x=>!removed.has(x[0])&&x.join(' ').toLowerCase().includes(q)).map(x=>panel(x[0],`<div class="c-inline">${b(x[1])}<p class="muted">${x[2]}</p>${l(x[3],'Open ↗')}<button class="btn btn-ghost" data-remove-save="${e(x[0])}">Remove</button></div>`)).join('')||'<div class="panel empty-state">No saved items match. <button class="btn" data-restore-saved>Restore samples</button></div>';};render();root.querySelector('input').oninput=render;root.addEventListener('click',ev=>{const t=ev.target.closest('[data-remove-save]');if(t){removed.add(t.dataset.removeSave);render();}if(ev.target.closest('[data-restore-saved]')){removed.clear();render();}if(ev.target.closest('[data-export-saved]'))U.download('nest-saved-preview.json',JSON.stringify(saved.filter(x=>!removed.has(x[0])),null,2),'application/json');});};
 S.supply=()=>top('Credit / Direct supply','Put liquidity to work','Compare the same asset, amount and horizon across registered lending venues.',l('positions','My positions'))+tabs('supply',creditTabs)+`<div class="c-detail-grid"><div class="stack">`+panel('Supply intent',`<form id="c-supply-form" class="stack"><div class="field-row">${field('Asset',`<select class="input" name="asset"><option>USDC</option><option>XLM</option></select>`)}${field('Amount',inp('amount','1000.00','inputmode="decimal" required pattern="[0-9]+(\\.[0-9]+)?"'))}</div><div class="field-row">${field('Comparison horizon · days',inp('horizon','90','type="number" min="1" max="3650" required'),'An assumption, not a maturity date')}${field('Venue',`<select class="input" name="venue"><option>Best available</option><option>Blend</option><option>Templar</option><option>XOXNO</option></select>`)}</div>${timing}<button class="btn btn-primary" type="submit">Compare supply</button></form>`)+`<section class="panel" id="c-supply-results" aria-live="polite"></section></div><aside class="stack">`+panel('How comparison works',facts([['Ranking','Estimated net yield at identical inputs'],['Rate','Variable APR · current rate assumption'],['Incentives','Separated from base yield'],['Capacity','Amount must be fully supportable'],['Exit','Liquidity, queue and collateral constraints']]))+panel('Your supplied positions',`${ident('Blend','1,000.00 USDC · sample balance')}<p class="muted mt-24">Withdrawals use the same action review and refresh position state.</p><button class="btn full-width" data-review="withdraw" data-title="Withdraw supplied USDC" data-venue="Blend" data-amount="100.00 USDC">Preview withdrawal</button>`)+`</aside></div>`+foot;
 B.supply=root=>{const form=root.querySelector('form'),box=root.querySelector('#c-supply-results');const compare=()=>{const f=new FormData(form),amount=f.get('amount'),asset=f.get('asset'),horizon=Number(f.get('horizon'));const valid=/^\d+(\.\d+)?$/.test(amount)&&Number(amount)>0;box.innerHTML=valid?`<div class="panel-head"><h2>Supply comparison</h2>${b('Fixture rates')}</div>`+table(['Venue','Base APR / incentives','Horizon return¹','Exit / capacity','Action'],[[ident('Blend'),'5.42% / none',money(Number(amount)*.0542*horizon/365),'Pool liquidity · 25,000 USDC',`<button class="btn btn-primary" data-review="deposit" data-venue="Blend" data-title="Supply ${e(asset)}" data-amount="${e(amount)} ${e(asset)}" data-withdrawal="Pool liquidity and collateral obligations constrain withdrawals.">Review</button>`],[ident('Templar'),'4.80% / none',money(Number(amount)*.048*horizon/365),'Queue + settlement · 10,000 USDC',`<button class="btn" data-review="deposit" data-venue="Templar" data-amount="${e(amount)} ${e(asset)}" data-withdrawal="Withdrawal request may enter a queue. Settlement availability is variable.">Review</button>`],[ident('XOXNO'),'Unavailable','—','Quote source unavailable',b('Excluded','warning')]])+'<p class="data-note panel-body">¹ Initial-rate estimate; excludes unknown network fees. Numbers illustrate layout and calculation only. XLM comparison requires fresh market data.</p>':'<div class="empty-state">Enter a positive decimal amount.</div>';const venue=f.get('venue');if(venue&&venue!=='Best available')box.querySelectorAll('tbody tr').forEach(row=>row.hidden=row.cells[0].textContent!==venue);if(asset==='XLM'||Number(amount)>10000){box.innerHTML='<div class="panel-body"><h2>No comparable fixture routes</h2><p class="muted mt-24">This sample covers up to 10,000 USDC. Keep the requested amount and asset unchanged; refresh registered markets in production.</p></div>';}};form.onsubmit=ev=>{ev.preventDefault();compare();};form.oninput=()=>{box.innerHTML='<div class="panel-body muted">Inputs changed. Compare again for a fresh result.</div>';};compare();};
 S.portfolio=()=>top('Wallet / Mainnet','Your portfolio','Confirmed balances, positions and exits with explicit accounting coverage.',l('fund','Receive')+l('transfer','Send',true))+tabs('portfolio',portfolioTabs)+`<section class="panel n-portfolio-summary" aria-label="Portfolio value"><div><span class="eyebrow">Net portfolio value · fixture</span><div class="portfolio-balance">$24,760.00</div><p>4 of 5 sources available · 25 Oct 2026, 14:32 UTC</p><div class="c-inline mt-24">${b('Partial coverage','warning')}${b('Mainnet · sample account')}</div></div><div class="n-summary-facts"><div><span>Gross assets</span><strong>$28,260</strong><small>Wallet + supply + vault receipts</small></div><div><span>Debt</span><strong class="negative">$3,500</strong><small>Subtracted once from assets</small></div></div></section><div class="n-portfolio-metrics"><article class="panel"><span class="eyebrow">Wallet / spendable</span><strong>$8,260</strong><small>USDC + XLM · reserve excluded</small></article><article class="panel"><span class="eyebrow">Direct supply</span><strong>$10,000</strong><small>Blend · underlying claim</small></article><article class="panel"><span class="eyebrow">Vault receipts</span><strong>$10,000</strong><small>Gami Labs · counted once</small></article><article class="panel"><span class="eyebrow">Pending exits</span><strong>1 request</strong><small>Settlement required before claim</small></article></div><section class="panel n-portfolio-chart"><div class="panel-head"><h2>Value breakdown</h2><div role="group" aria-label="Portfolio breakdown view"><button class="btn" data-portfolio-view="allocation" aria-pressed="true">Asset mix</button><button class="btn" data-portfolio-view="net" aria-pressed="false">Net value</button></div></div><div class="panel-body"><div data-allocation-view="allocation"><span class="data-note">Gross assets · receipt backing is excluded from these totals</span><div class="n-allocation" role="img" aria-label="Wallet 29.2%, direct supply 35.4%, vault receipts 35.4% of gross assets"><span style="--share:29.23%;--series:var(--nest-series-1)"></span><span style="--share:35.385%;--series:var(--nest-series-2)"></span><span style="--share:35.385%;--series:var(--nest-series-3)"></span></div><div class="n-allocation-legend"><div style="--series:var(--nest-series-1)"><span>Wallet</span><strong>$8,260.00</strong><small>29.2% of gross assets</small></div><div style="--series:var(--nest-series-2)"><span>Direct supply</span><strong>$10,000.00</strong><small>35.4% of gross assets</small></div><div style="--series:var(--nest-series-3)"><span>Vault receipts</span><strong>$10,000.00</strong><small>35.4% of gross assets</small></div></div></div><div data-allocation-view="net" hidden><div class="n-net-bridge"><div><small>Gross assets</small><strong>$28,260</strong></div><span>−</span><div><small>Liabilities</small><strong class="negative">$3,500</strong></div><span>=</span><div><small>Net value</small><strong>$24,760</strong></div></div><p class="data-note">Pledged collateral is already counted. Templar valuation is unavailable and excluded from the fresh total.</p></div></div><div class="n-portfolio-performance">${U.icon('info')}<p><b>Performance needs cost basis.</b> Acquisition costs are unknown. Lifetime P&amp;L and historical performance remain unavailable.</p></div></section><div class="c-detail-grid mt-24"><div class="stack">${panel('Positions & exits',table(['Position','Value','Accounting','Action'],[[ident('USDC','Liquid wallet balance'),'$7,260.00','Confirmed balance',l('transfer','Send')],[ident('XLM','Liquid wallet balance · reserve excluded'),'$1,000.00','Confirmed balance',l('transfer','Send')],[ident('Blend','Direct supply'),'$10,000.00','Underlying claim · one value',`<button class="btn" data-review="withdraw" data-venue="Blend" data-amount="100.00 USDC">Withdraw</button>`],[ident('Gami Labs','Vault receipt'),'$10,000.00','Backing shown as exposure only',l('vault-management','Request exit')],[ident('Blend','Debt / USDC'),'−$3,500.00','Liability · native risk',l('positions','Manage')]]))}${panel('Activity',table(['Action','Amount','State'],[['Supply USDC','1,000.00 USDC',l('plan?state=Confirmed','Confirmed receipt ↗')],['Redemption request','1,200.00 USDC',l('vault-management','Awaiting settlement ↗')]]),l('activity','All activity'))}</div><aside class="stack">${panel('Needs attention',`<p>One redemption is awaiting settlement.</p>${l('vault-management','Track request',true)}<hr><p class="muted">Templar valuation unavailable. Last known amount remains labeled and excluded from the fresh total.</p>${b('Partial coverage','warning')}`)}${panel('Underlying exposure','<p class="muted">Vault backing and collateral are decomposed for risk inspection. They are never added to receipt value a second time.</p>'+l('alerts','View alerts'))}</aside></div>`+foot;
 S.fund=()=>top('Portfolio / Funding','Receive on Stellar','Select the correct network, asset identity and destination before transferring.',l('portfolio','← Portfolio'))+tabs('fund',portfolioTabs)+`<div class="c-detail-grid"><div class="stack">${panel('Funding destination',`<div class="c-inline">${ident('Stellar','Mainnet · illustrative destination')}${b('Watch-only fixture','info')}</div><div class="stack mt-24">${field('Destination account',`<div class="c-address">DEMO_ACCOUNT — NOT A VALID FUNDING ADDRESS</div>`)}${field('Memo requirement','<div class="input">No memo for this self-custody sample account</div>','A custodial destination may require a memo. Production resolves this per receiver.')}<button class="btn" data-copy-demo>Copy demo label</button></div><div class="alert mt-24">Design specimen only. A verified account and network must be resolved before a real address or QR is displayed.</div>`)}${panel('Asset setup',facts([['Asset',ident('USDC','Issuer + network must match')],['Trustline','Required for issued assets · state from ledger'],['XLM reserve','Protocol base reserve + subentries + liabilities'],['Spendable XLM','Balance less reserve and fee maximum'],['Activation','Verify account exists before arrival expectations']]))}</div><aside class="stack">${panel('Arrival verification','<ol class="c-timeline"><li class="done"><b>Destination resolved</b><small>Account + network + memo requirement</small></li><li class="active"><b>Waiting for transfer</b><small>No matching confirmed transaction in sample</small></li><li><b>Verify on-chain receipt</b><small>Asset identity, amount and final ledger</small></li><li><b>Refresh balances</b><small>Only confirmed effects enter Portfolio</small></li></ol><button class="btn full-width" data-check-arrival>Check sample arrival</button>')}${panel('External funding','<p class="muted">Open a supported funding provider only after checking region, asset, fees and destination. Provider availability is configured by the backend.</p><button class="btn full-width" disabled>No funding provider configured</button>')}</aside></div>`;
 B.fund=root=>{root.querySelector('[data-copy-demo]').onclick=()=>{navigator.clipboard?.writeText('DEMO_ACCOUNT — NOT A VALID FUNDING ADDRESS').then(()=>U.toast('Demo label copied. This cannot receive funds.')).catch(()=>U.toast('Clipboard unavailable. Select the demo label manually.'));};root.querySelector('[data-check-arrival]').onclick=ev=>{ev.currentTarget.textContent='No arrival found · sample checked';U.toast('Fixture check complete — no network query made.');};};
 S.transfer=()=>top('Portfolio / Exit','Send assets','Resolve the receiver and memo, then inspect the exact transfer.',l('portfolio','← Portfolio'))+tabs('transfer',portfolioTabs)+`<div class="c-detail-grid"><div>${panel('Transfer details',`<form id="c-transfer" class="stack">${field('Asset',`<select class="input" name="asset"><option>USDC</option><option>XLM</option></select>`)}${field('Amount',inp('amount','','placeholder="0.00" inputmode="decimal" required'),'Spendable balance comes from ledger, reserves and fee maxima. No client-side Max estimate.')}${field('Destination account',inp('destination','','placeholder="G… or M…" required autocomplete="off"'),'Resolve canonical account, network and issuer acceptance.')}${field('Memo type',`<select class="input" name="memoType"><option value="none">None</option><option value="text">Text</option><option value="id">ID</option></select>`)}${field('Memo',inp('memo','','placeholder="Enter only when required" maxlength="28"'),'M-address routing and required memo checks must agree.')}<div id="c-transfer-errors" role="status"></div><button class="btn btn-primary">Inspect transfer</button></form>`)}<div class="mt-24" id="c-transfer-preview"></div></div><aside class="stack">${panel('Before signing',facts([['Receiver','Verify checksum and network'],['Memo','Required destinations cannot omit it'],['Balance','Native fee and reserve remain available'],['Issued asset','Trustline and authorization checked'],['Review','Exact amount, destination and max fees']]))}${panel('Moving out of Nest','<p class="muted">A wallet transfer across the tracked boundary is an external cash flow. Redeeming a vault or repaying debt inside the portfolio is an internal transformation.</p>')}</aside></div>`+foot;
 B.transfer=root=>{const f=root.querySelector('form');f.onsubmit=ev=>{ev.preventDefault();const d=new FormData(f),amount=d.get('amount'),dest=d.get('destination'),type=d.get('memoType'),memo=d.get('memo');let errors=[];if(!/^\d+(\.\d+)?$/.test(amount)||Number(amount)<=0)errors.push('Enter a positive decimal amount.');if(!/^(G[A-Z2-7]{55}|M[A-Z2-7]{68})$/.test(dest))errors.push('Enter a complete Stellar G or M account. Checksum verification remains a backend requirement.');if(type!=='none'&&!memo)errors.push('Enter the selected memo or explicitly choose None.');if(type==='id'&&!/^\d+$/.test(memo))errors.push('Memo ID must be an unsigned integer.');root.querySelector('#c-transfer-errors').innerHTML=errors.length?`<div class="alert">${errors.map(e).join('<br>')}</div>`:'';root.querySelector('#c-transfer-preview').innerHTML=errors.length?'':panel('Receiver inspection required',facts([['Amount',e(amount)+' '+e(d.get('asset'))],['Receiver',`<span class="mono c-wrap">${e(dest)}</span>`],['Memo',e(type)+' · '+e(memo||'None')],['Fee / reserve / trustline','Pending ledger and simulation checks']])+`<button class="btn full-width mt-24" disabled>Backend receiver verification required</button>`);};f.oninput=()=>root.querySelector('#c-transfer-preview').innerHTML='';};
 const activity=[['Supply USDC','1,000.00 USDC','Confirmed','Blend'],['Vault redemption','1,200.00 USDC','Awaiting external','Gami Labs'],['Swap XLM → USDC','250.00 XLM','Reconciling','Soroswap'],['Collateral addition','500.00 XLM','Cancelled','Blend']];
 S.activity=()=>top('Portfolio / History','Action history','Track the application plan separately from its transaction receipts.',l('portfolio','Portfolio'))+tabs('activity',portfolioTabs)+`<div class="toolbar"><input class="input" id="c-activity-search" aria-label="Search activity" placeholder="Search action or venue…"><select class="input" id="c-activity-status" aria-label="Filter action state"><option>All states</option>${activity.map(a=>`<option>${a[2]}</option>`).join('')}</select><button class="btn" data-export-activity>Export</button></div><div class="panel mt-24" id="c-activity-table"></div>`+foot;
 B.activity=root=>{const draw=()=>{let q=root.querySelector('input').value.toLowerCase(),s=root.querySelector('select').value;root.querySelector('#c-activity-table').innerHTML=table(['Action','Amount','Venue','State','Details'],activity.filter(a=>a.join(' ').toLowerCase().includes(q)&&(s==='All states'||s===a[2])).map(a=>[a[0],a[1],ident(a[3]),b(a[2],a[2]==='Confirmed'?'success':'info'),l('plan?state='+encodeURIComponent(a[2]),'Open plan ↗')]));};draw();root.querySelector('input').oninput=draw;root.querySelector('select').onchange=draw;root.querySelector('[data-export-activity]').onclick=()=>U.download('nest-activity-fixture.json',JSON.stringify(activity,null,2),'application/json');};
 const planStates=['Preparing','Awaiting review','Blocked','Wallet mismatch','Awaiting signature','Submitted','Reconciling','Awaiting next signature','Awaiting external','Partially completed','Confirmed','Failed','Expired','Cancelled'];
 S.plan=()=>top('Execution / Plan #NP-1042','Follow every step','Track the reviewed revision, confirmed effects and remaining exposure.',l('activity','← Activity'))+`<div class="toolbar"><label class="field c-inline"><span class="field-label">Lifecycle specimen</span><select class="input" id="c-plan-state">${planStates.map(s=>`<option ${s===(p().get('state')||'Reconciling')?'selected':''}>${s}</option>`).join('')}</select></label>${b('Mainnet · fixture')}${b('Revision 3 · policy 7')}</div><div class="c-detail-grid mt-24"><div class="stack"><section class="panel" id="c-plan-body" aria-live="polite"></section>${panel('Reviewed effects & fee limits',facts([['Input','1,000.00 USDC'],['Receiver','Registered Blend pool · canonical identity pending'],['Expected position effect','+ supply balance from parsed receipt'],['Network fee ceiling','Prepared amount in XLM required'],['Economic bounds','Plan revision + digest bound to approval'],['Withdrawal conditions','Pool liquidity and collateral obligations'],['Snapshot validity','Expired reviews require a fresh preparation']]))}</div><aside class="stack">${panel('Plan evidence',facts([['Plan ID','NP-1042 · illustrative'],['Intent','Supply USDC'],['Reviewed revision','3'],['Policy revision','7'],['Digest','DEMO_DIGEST · non-executable'],['Updated','25 Oct 2026 · 14:34 UTC']])+`<button class="btn full-width mt-24" data-export-plan>Export specimen</button>`)}${panel('Receipt',`<p class="muted">A real transaction hash and explorer link appear after submission. No fabricated hash links are emitted by this preview.</p>${b('No real receipt')}`)}</aside></div>`+foot;
 B.plan=root=>{const draw=()=>{const s=root.querySelector('select').value,done=s==='Confirmed',partial=s==='Partially completed',failed=['Failed','Expired','Cancelled','Blocked','Wallet mismatch'].includes(s);let msg=({'Preparing':'Comparing and simulating the requested action. No reviewed or signable revision exists yet.','Awaiting review':'The prepared revision is ready for owner review. A wallet signature has not been requested.','Blocked':'A required policy or capability check failed. No signing or submission is available.','Wallet mismatch':'Expected account or network differs. Invalidate this revision before re-preparing.'})[s]|| (done?'Confirmed token effects parsed. Portfolio can now refresh.':partial?'Step 1 completed; step 2 stopped. Show actual remaining exposure before a new recovery plan.':s==='Reconciling'?'Submission response is unresolved. Reconcile the existing hash before permitting a replacement.':s==='Awaiting signature'?'Keep the exact reviewed revision visible while the wallet asks for approval.':s==='Awaiting external'?'The venue accepted the request; external settlement remains pending.':s==='Awaiting next signature'?'Prior step confirmed. Fresh safety checks precede the next explicit signature.':failed?'This plan cannot submit in its current state. Preserve evidence and draft a fresh plan when appropriate.':'Submission was accepted. Confirmation and parsed effects are still pending.');root.querySelector('#c-plan-body').innerHTML=`<div class="panel-head"><h2>${s}</h2>${b(done?'Confirmed effects':partial?'Remaining exposure':failed?'Inactive':'In progress',done?'success':partial?'warning':'info')}</div><div class="panel-body"><p>${msg}</p><ol class="c-timeline"><li class="${s==='Preparing'?'active':'done'}"><b>Prepared and simulated</b><small>Revision 3 · explicit application validation</small></li><li class="${['Preparing','Awaiting review','Blocked','Wallet mismatch'].includes(s)?'':'done'}"><b>Review accepted</b><small>Exact economic bounds and policy 7</small></li><li class="${s==='Awaiting signature'?'active':['Preparing','Awaiting review','Blocked','Wallet mismatch'].includes(s)?'':'done'}"><b>Wallet signature</b><small>Stale or mutated payloads rejected</small></li><li class="${done?'done':['Preparing','Awaiting review','Awaiting signature','Blocked','Wallet mismatch'].includes(s)?'':'active'}"><b>${done?'Ledger confirmed':'Submit and reconcile'}</b><small>Receipt pending in this specimen</small></li><li class="${done?'done':''}"><b>Parse effects and refresh positions</b><small>${done?'Confirmed effects only':'Not complete until outcome is known'}</small></li></ol>${partial?'<div class="alert"><b>Remaining exposure</b><p>500 USDC supplied; subsequent collateral step did not complete. Production uses actual receipt deltas, never this fixture.</p><button class="btn" data-review="withdraw" data-title="Review separate recovery action" data-amount="500.00 USDC">Draft recovery review</button></div>':''}${s==='Awaiting signature'?'<button class="btn" disabled>Waiting for wallet · specimen</button> <button class="btn btn-ghost" data-plan-cancel>Preview cancellation</button>':''}${['Reconciling','Submitted'].includes(s)?'<div class="disclosure">Closing the page does not cancel a submitted transaction. Resume by persisted plan ID and last event ID.</div>':''}${done?l('portfolio','View updated portfolio',true):''}</div>`;};draw();root.querySelector('select').onchange=draw;root.querySelector('[data-export-plan]').onclick=()=>U.download('nest-plan-specimen.json',JSON.stringify({id:'NP-1042',revision:3,state:root.querySelector('select').value,fixture:true},null,2),'application/json');root.addEventListener('click',ev=>{if(ev.target.closest('[data-plan-cancel]')){root.querySelector('select').value='Cancelled';draw();}});};
 S['vault-management']=()=>top('Vaults / Owned positions','Redemptions & rewards','Track requests and inspect rewards lost before withdrawing a campaign lot.',l('vault-detail','Vault details')+l('portfolio','Portfolio'))+`<div class="grid-2">${panel('Pending redemption',`${ident('Gami Labs','Evergreen USDC vault')}${facts([['Requested amount','1,200.00 USDC'],['State',b('Awaiting settlement','info')],['Earliest availability','Unknown · liquidity dependent'],['Request receipt','Illustrative request; no chain receipt'],['Next step','Claim after venue confirms availability']])}<ol class="c-timeline mt-24"><li class="done"><b>Request recorded</b><small>Receipt shares locked or burned per adapter model</small></li><li class="active"><b>Settlement pending</b><small>Keep value classified as a pending receivable</small></li><li><b>Claim available assets</b><small>Requires a separate supported claim action</small></li></ol><button class="btn" data-settlement-ready>Show claimable specimen</button><div id="c-claim-state" class="mt-24"></div>`)}${panel('Campaign deposit lots',`${ident('Sentora','XLM campaign · sample lots')}<div class="mt-24">${table(['Lot','Principal','Accrued / claimable'],[['Lot 01 · 01 Oct','2,000 XLM','24 XLM / 8 XLM'],['Lot 02 · 12 Oct','1,000 XLM','6 XLM / 0 XLM']])}</div><form id="c-lot-form" class="stack mt-24">${field('Select lot',`<select class="input" name="lot"><option value="1">Lot 01</option><option value="2">Lot 02</option></select>`)}${field('Withdraw · XLM',inp('amount','500','inputmode="decimal" required'))}<div id="c-lot-impact"></div></form><p class="data-note">Reward forfeiture is a fixture schedule. Production computes per-lot rules, deadlines and vested versus claimable amounts.</p>`)}</div>`+foot;
 B['vault-management']=root=>{root.querySelector('[data-settlement-ready]').onclick=()=>root.querySelector('#c-claim-state').innerHTML='<div class="disclosure">Claimable specimen · settlement evidence must be refreshed before review.</div><button class="btn btn-primary mt-24" data-review="claim" data-venue="Gami Labs" data-amount="1,200.00 USDC">Review claim</button>';const f=root.querySelector('form'),draw=()=>{const d=new FormData(f),n=Number(d.get('amount')),lot=d.get('lot'),principal=lot==='1'?2000:1000;root.querySelector('#c-lot-impact').innerHTML=(!Number.isFinite(n)||n<=0||n>principal)?'<div class="alert">Amount must be within the selected lot.</div>':`<div class="disclosure"><b>Withdrawal conditions / sample</b><br>Release depends on campaign terms. Proportional unvested rewards forfeited: ${(n/principal*(lot==='1'?16:6)).toFixed(2)} XLM. Claimable rewards remain separate.</div><button type="button" class="btn btn-primary full-width mt-24" data-review="withdraw" data-venue="Sentora" data-title="Withdraw campaign lot ${lot}" data-amount="${e(d.get('amount'))} XLM">Review lot withdrawal</button>`;};f.oninput=draw;draw();};
 S['automation-history']=()=>top('Lab / Automation #A-102','XLM price watch','Inspect observations, trigger evidence and the proposed action.',l('lab-automation','← Rule builder')+l('connections','Connections'))+`<div class="panel c-inline panel-body mb-24">${b('Preview rule · paused','warning')}<span class="mono">Revision 4</span><button class="btn" data-rule-pause>Preview resume</button><span class="data-note">No real schedule or execution authority</span></div><div class="c-detail-grid"><div class="stack">${panel('Rule definition',facts([['Source','Registered XLM / USDC price feed'],['Condition','Crosses above 0.195 USDC'],['Action','Propose exact-input swap · 250 XLM'],['Unknown observation','Skip action, retain diagnostic'],['Deduplication','Rule revision + observation identity'],['Cooldown','Explicit configured window required']]))}${panel('Evaluation history',table(['Observation','Evidence','Result','Action'],[['14:31:00 UTC','0.185 → 0.198','True · crossed threshold','Proposal created'],['14:32:00 UTC','Duplicate observation','True · deduplicated','No new proposal'],['14:33:00 UTC','Provider unavailable','Unknown · skip','No action'],['14:34:00 UTC','0.198 → 0.197','False · already above','No action']]))}${panel('Trigger evidence','<p class="muted">Each evaluation pins source, observed time, received time, normalized typed value, rule revision and evaluation ID. Social content is data; it cannot change policy or action authority.</p>')}</div><aside class="stack">${panel('Proposal #P-041',facts([['Origin','Rule A-102 · revision 4'],['Spend','250.00 XLM'],['Action','Propose swap to USDC'],['Quote','Not yet prepared'],['Authority','Explicit review required']])+`<button class="btn btn-primary full-width mt-24" data-review="trade" data-title="Review automation proposal" data-amount="250.00" data-input-asset="XLM" data-output-asset="USDC">Prepare proposal specimen</button><button class="btn full-width mt-24" data-dismiss-proposal>Dismiss specimen</button>`)}${panel('Source health','<p class="muted">Stale or unauthorized sources produce Unknown. Reconnection never activates paused rules automatically.</p>'+l('connections','Inspect access'))}</aside></div>`+foot;
 B['automation-history']=root=>{root.querySelector('[data-rule-pause]').onclick=ev=>{const on=ev.currentTarget.textContent.includes('resume');ev.currentTarget.textContent=on?'Preview pause':'Preview resume';root.querySelector('.badge').textContent=on?'Preview rule · active':'Preview rule · paused';};root.querySelector('[data-dismiss-proposal]').onclick=ev=>{ev.currentTarget.closest('.panel-body').innerHTML='<h3>Proposal dismissed</h3><p class="muted">The rule remains unchanged. No transaction was prepared.</p>';};};
 S.connections=()=>top('Workspace / Sources','Connections','See granted access, health, entitlement and dependent rules.',l('automation-history','Rule history'))+`<div class="grid-2">${panel('X / social read access',`${ident('X','Official OAuth · no financial authority')}<div class="mt-24">${facts([['Connection',b('Expired specimen','warning')],['Granted scopes','tweet.read · users.read · offline.access'],['Entitled datasets','Unavailable until application configuration resolves'],['Cadence / quota','Provider and app budget dependent'],['Dependent rules','2 paused rules']])}</div><div class="c-inline mt-24"><button class="btn btn-primary" data-open="connection-x">Reconnect</button><button class="btn" data-disconnect>Disconnect specimen</button></div><div id="c-connection-note" class="mt-24"></div>`)}${panel('Market & protocol sources',facts([['Stellar RPC','Managed public-chain source'],['Soroswap','Backend credentials only'],['DefiLlama','Dated public snapshot'],['RWA.xyz','Dated public snapshot'],['Secrets','Never exposed in client UI']])+l('research-defi','Inspect research'))}</div>`+foot;
 B.connections=root=>root.querySelector('[data-disconnect]').onclick=()=>root.querySelector('#c-connection-note').innerHTML='<div class="disclosure"><b>Disconnected specimen</b><br>Tokens revoked by production connector. Dependent rules remain paused; reconnect and explicit activation are separate actions.</div>';
 let readAlerts=false;
 S.alerts=()=>top('Workspace / Monitor','Alerts','Source health, position risk and workflow updates.',l('portfolio','Portfolio'))+`<div class="toolbar"><button class="btn" data-alerts-read>Mark samples as read</button>${l('connections','Source settings')}</div><div class="stack mt-24" id="c-alert-list">${[['warning','Position risk','Blend post-action health is approaching the saved warning threshold.','positions'],['info','Settlement pending','Vault redemption is awaiting external availability.','vault-management'],['warning','Source authorization','X access expired; two dependent rules remain paused.','connections']].map(([tone,title,msg,id])=>panel(title,`<div class="c-inline">${b(readAlerts?'Read':'Unread',tone)}<span class="data-note">25 Oct · illustrative alert</span></div><p class="muted mt-24">${msg}</p>${l(id,'Inspect ↗')}`)).join('')}</div>`;
 B.alerts=root=>root.querySelector('[data-alerts-read]').onclick=()=>{readAlerts=true;root.querySelectorAll('#c-alert-list .badge').forEach(x=>x.textContent='Read');U.toast('Sample alerts marked read in this session.');};
 S.conversations=()=>top('Ask Nest / Workspace','Conversations','Research context, source evidence and application-owned proposals.',l('lab-memory','Inspect memory'))+`<div class="c-chat-layout"><aside class="panel panel-body"><span class="eyebrow">Verified-wallet history / sample</span><button class="btn full-width" data-new-chat>New conversation</button><div class="stack mt-24"><button class="c-chat-choice active">Compare USDC supply<small>Today · 3 sources</small></button><button class="c-chat-choice">Understand BENJI access<small>Yesterday · research only</small></button><button class="c-chat-choice">Review vault exit<small>Yesterday · pending request</small></button></div><p class="data-note mt-24">Guests can chat transiently. Connect and verify ownership to persist.</p></aside><section class="panel c-chat-panel"><div class="panel-head"><h2 id="c-chat-title">Compare USDC supply</h2><select class="input" id="c-agent-state" aria-label="Assistant state"><option>Answer ready</option><option>Streaming</option><option>Provider failure</option><option>Quota exhausted</option></select></div><div class="panel-body stack" id="c-chat-body"><div class="c-message user">Compare 1,000 USDC for 90 days. I need a clear withdrawal path.</div><div class="c-message"><p>Blend and Templar have different exit mechanics. Compare the same capital and horizon, then inspect queue or liquidity restrictions before preparing a deposit.</p><div class="c-inline">${l('protocol-detail','Blend evidence ↗')}${l('supply','Supply comparison ↗')}</div><div class="disclosure mt-24"><b>Application proposal</b><br>Supply 1,000.00 USDC · venue and quote still require preparation.</div><button class="btn mt-24" data-review="deposit" data-venue="Blend" data-amount="1,000.00 USDC">Inspect sample proposal</button></div><div id="c-agent-status" role="status"></div></div><form id="c-chat-form" class="panel-body"><label class="field"><span class="field-label">Message Nest</span><textarea class="input" rows="3" placeholder="Ask about a protocol, position or action…" required></textarea></label><div class="c-inline mt-24"><button class="btn btn-primary">Send specimen</button><button type="button" class="btn" data-stop-response>Stop response</button><button type="button" class="btn" data-retry-response>Retry</button></div><p class="data-note mt-24">Tool progress summarizes work. Hidden reasoning, credentials and signed payloads never appear.</p></form></section></div>`;
 B.conversations=root=>{const status=root.querySelector('#c-agent-status');root.querySelector('#c-agent-state').onchange=ev=>{status.innerHTML=({Streaming:'<div class="disclosure">Reading registered markets… <span class="mono">2 / 3 sources</span></div>','Provider failure':'<div class="alert">Assistant provider unavailable. Retry or continue with manual forms.</div>','Quota exhausted':'<div class="alert">AI allowance reached. Research and manual actions remain available.</div>'})[ev.target.value]||'<p class="muted">Response complete.</p>';};root.querySelector('form').onsubmit=ev=>{ev.preventDefault();const t=root.querySelector('textarea'),msg=document.createElement('div');msg.className='c-message user';msg.textContent=t.value;root.querySelector('#c-chat-body').append(msg);t.value='';status.textContent='Local conversation specimen · no model request sent.';};root.querySelector('[data-stop-response]').onclick=()=>status.textContent='Response stopped. Any prepared application plan remains separate.';root.querySelector('[data-retry-response]').onclick=()=>status.textContent='Retry specimen ready. No duplicate financial plan created.';root.querySelectorAll('.c-chat-choice').forEach(x=>x.onclick=()=>{root.querySelectorAll('.c-chat-choice').forEach(c=>c.classList.toggle('active',c===x));root.querySelector('#c-chat-title').textContent=x.childNodes[0].textContent;status.textContent='Conversation selection specimen.';});root.querySelector('[data-new-chat]').onclick=()=>{root.querySelector('#c-chat-title').textContent='New conversation';root.querySelectorAll('#c-chat-body .c-message').forEach(m=>m.remove());status.textContent='Transient conversation ready.';};};
 S['policy-states']=()=>top('Guardrails / State review','Your execution preferences','Wallet-scoped draft, explicit save and version-conflict handling.',`<button class="btn btn-primary" data-open="guardrails">Open Guardrails drawer</button>`)+`<div class="c-detail-grid"><div class="stack">${panel('Saved policy / revision 7',facts([['Wallet / network','DEMO_ACCOUNT · Stellar Mainnet'],['Slippage','Suggested 0.5% · not accepted'],['Impact warning','Suggested above 1% · not accepted'],['Quote maximum age','Suggested 30 s · not accepted'],['Fees','Review prepared maxima · extra ceiling unset'],['Lending','Venue-native warning and minimum separate'],['Optional amount caps','All off / unset']]))}${panel('Draft state specimens',`<label class="field"><span class="field-label">Review state</span><select class="input" id="c-policy-state"><option>Unsaved changes</option><option>Validation error</option><option>Version conflict</option><option>Saved</option><option>Wallet scope changed</option></select></label><div class="mt-24" id="c-policy-body" role="status"></div>`)}</div><aside class="stack">${panel('Effective rules','<ul class="c-bullets"><li>Chain, oracle and venue validity always apply.</li><li>A warning remains distinct from a blocker.</li><li>Saving preferences invalidates affected plans.</li><li>Saving never approves a transaction.</li><li>AI and memory cannot accept a suggestion.</li></ul>')}${panel('Versioned save','<p class="muted">POST /api/policy/revisions uses the expected revision and an idempotency key. A conflict keeps the draft available for comparison. The preview never writes a policy.</p>')}</aside></div>`;
 B['policy-states']=root=>{const draw=()=>{const state=root.querySelector('select').value;root.querySelector('#c-policy-body').innerHTML=({'Unsaved changes':'<div class="disclosure">Draft differs from revision 7. Cancel discards only after an explicit choice; Save is the only persistence action.</div>','Validation error':'<div class="alert">Quote maximum age must be a positive integer. Keep all draft fields and focus the invalid input.</div>','Version conflict':'<div class="alert"><b>Saved revision changed to 8</b><p>Your draft remains intact. Review the latest revision before applying changes.</p><button class="btn" data-policy-compare>Compare with latest</button></div>','Saved':'<div class="disclosure">Saved specimen · revision 8. Invalidate affected prepared plans and request a fresh preview. No action executed.</div>','Wallet scope changed':'<div class="alert">Account or network changed. Reload preferences for the new scope; never carry an unsaved draft across accounts.</div>'})[state];};draw();root.querySelector('select').onchange=draw;root.addEventListener('click',ev=>{if(ev.target.closest('[data-policy-compare]'))U.toast('Revision 7 draft retained · review revision 8 before saving.');});};
 S['wallet-access']=()=>top('Wallet / Session','Choose your access','Read public data, watch an address, or verify wallet ownership.',l('portfolio','Portfolio'))+`<div class="grid-3">${panel('Explore as guest','<p class="muted">Research and amount-aware comparisons work without a wallet. Personal state remains transient.</p>'+l('research-defi','Explore research'))}${panel('Watch an address','<form id="c-watch" class="stack">'+field('Public account',inp('account','','placeholder="G…" required'))+'<button class="btn">Inspect watch state</button><div id="c-watch-result" role="status"></div></form>')}${panel('Connect & verify','<p class="muted">Provider connection identifies an address. A server challenge proves ownership before saving personal state.</p><button class="btn btn-primary full-width" data-open="wallet">Connect wallet</button>')}</div><div class="c-detail-grid mt-24">${panel('Ownership verification',`<ol class="c-timeline"><li class="done"><b>Choose provider and network</b><small>Address does not prove ownership</small></li><li class="active"><b>Sign ownership challenge</b><small>Origin, nonce, expiry and network bound · not a financial transaction</small></li><li><b>Server verifies and issues session</b><small>Secure cookie · account-scoped personal data</small></li></ol>`)}${panel('Mismatch & cancellation','<div class="alert"><b>Wallet / network mismatch</b><p>Expected Mainnet and the reviewed account. Switching invalidates prepared plans before a fresh review.</p></div><p class="muted mt-24">Rejected challenge returns to unverified state. Expired sessions retain draft inputs and require verification again.</p>')}</div>`+foot;
 B['wallet-access']=root=>root.querySelector('form').onsubmit=ev=>{ev.preventDefault();const a=new FormData(ev.currentTarget).get('account');root.querySelector('#c-watch-result').innerHTML=/^G[A-Z2-7]{55}$/.test(a)?'<div class="disclosure">Read-only watch specimen. No signer authority or private history access. Backend checksum and ledger verification required.</div>':'<div class="alert">Enter a complete public Stellar account.</div>';};
 S['backtest-run']=()=>top('Lab / Backtest run','Inspect the run','Compare reproducible assumptions, event coverage and modeled costs.',l('lab-backtests','← Backtests'))+`<div class="alert alert-info mb-24">Synthetic sample results · P1 historical replay integration remains deferred.</div><div class="grid-4">${U.stat('Strategy','Allocation band','XLM / USDC · synthetic')}${U.stat('Observations','16','Sample fixture, not historical data')}${U.stat('Execution','Next observation','No look-ahead fills')}${U.stat('Costs','Modeled','Fee + slippage assumptions')}</div><div class="c-detail-grid mt-24"><div class="stack">${panel('Run comparison',table(['Measure','Run A','Run B'],[['Allocation rule','60% XLM ± 10%','50% XLM ± 10%'],['Dataset','Same synthetic sample','Same synthetic sample'],['Liquidation model','Not modeled','Not modeled'],['Benchmark','Buy and hold','Buy and hold'],['Return / drawdown','Recompute in Backtests','Recompute in Backtests']]))}${panel('Data & reproducibility',facts([['Coverage','16 synthetic price observations'],['Snapshot','Fixed in local backtest module'],['Strategy revision','Rules and parameters pinned per run'],['Event audit','Fills, rebalance, modeled costs'],['Unsupported inputs','Do not substitute unavailable historical data']]))}</div><aside class="stack">${panel('Re-run or export','<p class="muted">Use the working Backtests view to run the deterministic sample, compare session results, and export its full audit.</p>'+l('lab-backtests','Open sample runner',true))}${panel('Interpretation','<p class="muted">Simulated results are never included in Portfolio returns or labeled validated alpha.</p>')}</aside></div>`;
 S['learning-runs']=()=>top('Lab / P1 design','Learning runs','A bounded research experiment with an explicit objective and evidence.',l('lab-memory','Memory')+l('lab-backtests','Backtests'))+`<div class="alert alert-info mb-24">Deferred P1 screen design · no background agent or experiment is running.</div><div class="c-detail-grid"><div class="stack">${panel('Experiment draft',`<form id="c-learning" class="stack">${field('Objective',`<textarea class="input" required rows="3">Compare USDC supply outcomes under different liquidity needs.</textarea>`)}<div class="field-row">${field('Read / evaluation budget',inp('budget','20','type="number" min="1" required'))}${field('Maximum runtime · minutes',inp('runtime','10','type="number" min="1" required'))}</div>${field('Allowed tools','<div class="input">Read research · inspect snapshots · run approved simulations</div>')}<button class="btn btn-primary">Review experiment specimen</button><div id="c-learning-result" role="status"></div></form>`)}${panel('Evidence & findings','<div class="c-coverage"><h3>No experiment results yet</h3><p>Use frozen sanitized recorded tasks, simulations and backtests. Evaluate held-out regressions, factual support, schema/asset/math correctness, latency and cost.</p></div>')}</div><aside class="stack">${panel('Authority boundaries','<ul class="c-bullets"><li>No financial submission or signing.</li><li>No policy writes.</li><li>Budget and stop reason visible.</li><li>No live-fund experiments or production credentials.</li><li>Findings remain proposals until accepted.</li><li>Runtime changes use developer review and normal deployment.</li><li>Memory acceptance is a separate choice.</li></ul>')}${panel('Progress specimen',facts([['State','Draft'],['Reads / trials','0 / 0'],['Elapsed','Not started'],['Stop condition','Budget, runtime, cancellation or completion'],['Frozen inputs','Task/data/model/Pi/prompt/skill/tool versions + hashes'],['Candidate surfaces','Explanation, prompt or skill guidance only'],['Promotion','Versioned human-reviewed proposal + regression evidence'],['Rollback','Prior accepted version retained']]))}</aside></div>`;
 B['learning-runs']=root=>root.querySelector('form').onsubmit=ev=>{ev.preventDefault();root.querySelector('#c-learning-result').innerHTML='<div class="disclosure">Experiment draft reviewed locally. Background execution is unavailable in this prototype.</div>';};
 const originalVault=S['vault-detail'],originalBacktests=S['lab-backtests'];
 S['vault-detail']=()=>`<div class="c-utility-links">${l('vault-management','Manage redemptions & lots')}</div>`+originalVault();
 S['lab-backtests']=()=>`<div class="c-utility-links">${l('backtest-run','Run detail & coverage')}${l('learning-runs','Learning runs · P1')}</div>`+originalBacktests();
 // Integrate new routes into original surfaces, retaining the selected two Research tabs.
 const originalBorrow=S.borrow,originalPositions=S.positions,originalAutomation=S['lab-automation'],originalMemory=S['lab-memory'];
 S.borrow=()=>originalBorrow().replace(/<a([^>]*?)href="#positions"/,'<a class="tab" href="#supply">Supply</a><a$1href="#positions"');
 S.positions=()=>originalPositions().replace(/<a([^>]*?)href="#positions"/,'<a class="tab" href="#supply">Supply</a><a$1href="#positions"');
 S['lab-automation']=()=>`<div class="c-utility-links">${l('automation-history','Evaluations & proposals')}${l('connections','Connections')}</div>`+originalAutomation();
 S['lab-memory']=()=>`<div class="c-utility-links">${l('chat','Conversations')}${l('learning-runs','Learning runs · P1')}</div>`+originalMemory();
 document.addEventListener('click',ev=>{const mark=ev.target.closest('[data-bookmark]');if(mark){mark.textContent='Saved in preview';U.toast('Bookmark specimen saved in this session · verify wallet to persist.');}});
})();
